<!doctype html>
<html lang="es">
<head>
    <meta charset="utf-8">
    <title>Reportes generales</title>
    <style>
        *{box-sizing:border-box}body{font-family:Arial,sans-serif;margin:0;color:#172554;background:#eef2ff}.hoja{max-width:1200px;margin:24px auto;background:#fff;padding:28px;border-radius:14px}.cabecera{display:flex;justify-content:space-between;gap:20px;border-bottom:3px solid #4f46e5;padding-bottom:16px}.cabecera h1{margin:0 0 4px;font-size:24px}.cabecera p,.muted{margin:3px 0;color:#64748b;font-size:12px}.acciones{margin:0 auto 12px;max-width:1200px;text-align:right}.acciones button{border:0;border-radius:9px;background:#4f46e5;color:white;padding:10px 18px;font-weight:bold}.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin:18px 0}.kpi{border:1px solid #c7d2fe;background:#eef2ff;border-radius:10px;padding:10px}.kpi small{display:block;text-transform:uppercase;color:#4338ca;font-weight:bold}.kpi b{display:block;margin-top:4px;font-size:19px}.bloque{margin-top:22px;page-break-inside:auto}.bloque h2{margin:0 0 3px;font-size:16px}.bloque>p{margin:0 0 10px;color:#64748b;font-size:11px}table{width:100%;border-collapse:collapse;font-size:10px}th{background:#e0e7ff;color:#312e81;text-transform:uppercase;text-align:left}th,td{border:1px solid #cbd5e1;padding:6px;vertical-align:top}tr{page-break-inside:avoid}.derecha{text-align:right}.centro{text-align:center}.sin-datos{text-align:center;color:#64748b;padding:16px}.pie{margin-top:22px;padding-top:10px;border-top:1px solid #cbd5e1;color:#64748b;font-size:10px;display:flex;justify-content:space-between}@media print{body{background:white}.acciones{display:none}.hoja{max-width:none;margin:0;padding:0;border-radius:0}@page{size:A4 landscape;margin:10mm}.bloque{page-break-before:auto}.cabecera{break-inside:avoid}.kpis{break-inside:avoid}}
    </style>
</head>
<body>
<div class="acciones"><button onclick="window.print()">Imprimir reporte</button></div>
<main class="hoja">
    <header class="cabecera">
        <div><h1><?= htmlspecialchars($institucion['nombre'] ?? 'Colegio') ?></h1><p><?= htmlspecialchars($institucion['direccion'] ?? '') ?></p><p><?= htmlspecialchars(trim(($institucion['telefono'] ?? '') . ' · ' . ($institucion['correo'] ?? ''), ' ·')) ?></p></div>
        <div class="derecha"><h1>Reportes generales</h1><?php if ($periodo): ?><p><b><?= htmlspecialchars($periodo['nombre']) ?></b> · <?= htmlspecialchars($periodo['estado']) ?></p><p><?= htmlspecialchars($desde) ?> al <?= htmlspecialchars($hasta) ?></p><?php endif; ?><p>Generado: <?= date('d/m/Y H:i') ?></p><p>Usuario: <?= htmlspecialchars($_SESSION['usuario']['nombre'] ?? $_SESSION['usuario']['rol'] ?? 'Sistema') ?></p></div>
    </header>

    <?php if (!$periodo): ?><p class="sin-datos">No existe un período académico para generar el reporte.</p><?php else: ?>
    <section class="kpis">
        <div class="kpi"><small>Matriculados</small><b><?= number_format($kpis['matriculados']) ?></b></div><div class="kpi"><small>Capacidad</small><b><?= number_format($kpis['capacidad']) ?></b></div><div class="kpi"><small>Vacantes</small><b><?= number_format($kpis['vacantes']) ?></b></div><div class="kpi"><small>Asistencia alumnos</small><b><?= number_format($kpis['asistencia_alumnos'],1) ?>%</b></div><div class="kpi"><small>Personal reportado</small><b><?= number_format($kpis['personal_reportado']) ?></b></div><div class="kpi"><small>Incidencias pendientes</small><b><?= number_format($kpis['incidencias_pendientes']) ?></b></div>
    </section>

    <section class="bloque"><h2>Matrículas por nivel, grado y sección</h2><p>Capacidad, ocupación y estados de matrícula del período seleccionado.</p><table><thead><tr><th>Nivel</th><th>Grado</th><th>Sección</th><th>Capacidad</th><th>Activos</th><th>Retirados</th><th>Egresados</th><th>Anulados</th><th>Vacantes</th><th>Ocupación</th></tr></thead><tbody><?php foreach ($matriculas as $fila): $capacidad=$fila['capacidad']===null?null:(int)$fila['capacidad']; $ocupacion=$capacidad?((int)$fila['activos']/$capacidad)*100:0; ?><tr><td><?= htmlspecialchars($fila['nivel']) ?></td><td><?= htmlspecialchars($fila['grado']) ?></td><td><?= htmlspecialchars($fila['seccion']) ?></td><td><?= $capacidad===null?'Sin límite':$capacidad ?></td><td><?= (int)$fila['activos'] ?></td><td><?= (int)$fila['retirados'] ?></td><td><?= (int)$fila['egresados'] ?></td><td><?= (int)$fila['anulados'] ?></td><td><?= $capacidad===null?'—':max(0,$capacidad-(int)$fila['activos']) ?></td><td><?= $capacidad?number_format($ocupacion,1).'%':'No aplica' ?></td></tr><?php endforeach; ?><?php if(!$matriculas): ?><tr><td colspan="10" class="sin-datos">Sin registros</td></tr><?php endif; ?></tbody></table></section>

    <section class="bloque"><h2>Asistencia de alumnos por sección</h2><p>Porcentaje sobre jornadas registradas en el rango.</p><table><thead><tr><th>Sección</th><th>Alumnos</th><th>Jornadas</th><th>Asistencias</th><th>Puntuales</th><th>Tardanzas</th><th>Faltas</th><th>Justificadas</th><th>Minutos tardanza</th><th>Asistencia</th></tr></thead><tbody><?php foreach ($asistenciaSecciones as $fila): ?><tr><td><?= htmlspecialchars($fila['seccion']) ?></td><td><?= $fila['alumnos'] ?></td><td><?= $fila['jornadas'] ?></td><td><?= $fila['asistencias'] ?></td><td><?= $fila['puntuales'] ?></td><td><?= $fila['tardanzas'] ?></td><td><?= $fila['faltas'] ?></td><td><?= $fila['justificadas'] ?></td><td><?= $fila['minutos_tardanza'] ?></td><td><?= number_format($fila['porcentaje'],1) ?>%</td></tr><?php endforeach; ?><?php if(!$asistenciaSecciones): ?><tr><td colspan="10" class="sin-datos">Sin registros</td></tr><?php endif; ?></tbody></table></section>

    <section class="bloque"><h2>Detalle de asistencia por alumno</h2><p>Alumnos activos, retirados y egresados; se excluyen matrículas anuladas.</p><table><thead><tr><th>Alumno</th><th>Código</th><th>Nivel / grado / sección</th><th>Estado</th><th>Jornadas</th><th>Puntual</th><th>Tardanzas</th><th>Faltas</th><th>Justificadas</th><th>Min. tardanza</th><th>Asistencia</th></tr></thead><tbody><?php foreach ($asistenciaAlumnos as $fila): ?><tr><td><?= htmlspecialchars($fila['alumno']) ?></td><td><?= htmlspecialchars($fila['codigo_alumno']) ?></td><td><?= htmlspecialchars($fila['nivel'].' · '.$fila['grado'].' '.$fila['seccion']) ?></td><td><?= htmlspecialchars($fila['estado_matricula']) ?></td><td><?= (int)$fila['jornadas'] ?></td><td><?= (int)$fila['puntuales'] ?></td><td><?= (int)$fila['tardanzas'] ?></td><td><?= (int)$fila['faltas'] ?></td><td><?= (int)$fila['justificadas'] ?></td><td><?= (int)$fila['minutos_tardanza'] ?></td><td><?= number_format($fila['porcentaje'],1) ?>%</td></tr><?php endforeach; ?><?php if(!$asistenciaAlumnos): ?><tr><td colspan="11" class="sin-datos">Sin registros</td></tr><?php endif; ?></tbody></table></section>

    <section class="bloque"><h2>Asistencia de docentes y administrativos</h2><p>Jornadas individuales y sesiones docentes.</p><table><thead><tr><th>Trabajador</th><th>Código</th><th>Tipo / cargo</th><th>Jornadas</th><th>Puntual</th><th>Tardanzas</th><th>Faltas</th><th>Justificadas</th><th>Incompletas</th><th>Min. tardanza</th><th>Horas</th><th>Asistencia</th></tr></thead><tbody><?php foreach ($asistenciaPersonal as $fila): ?><tr><td><?= htmlspecialchars($fila['trabajador']) ?></td><td><?= htmlspecialchars($fila['codigo_trabajador'] ?: 'Sin código') ?></td><td><?= htmlspecialchars($fila['tipo'].' · '.$fila['cargo']) ?></td><td><?= (int)$fila['jornadas'] ?></td><td><?= (int)$fila['puntuales'] ?></td><td><?= (int)$fila['tardanzas'] ?></td><td><?= (int)$fila['faltas'] ?></td><td><?= (int)$fila['justificadas'] ?></td><td><?= (int)$fila['incompletas'] ?></td><td><?= (int)$fila['minutos_tardanza'] ?></td><td><?= number_format((int)$fila['minutos_trabajados']/60,1) ?></td><td><?= number_format($fila['porcentaje'],1) ?>%</td></tr><?php endforeach; ?><?php if(!$asistenciaPersonal): ?><tr><td colspan="12" class="sin-datos">Sin registros</td></tr><?php endif; ?></tbody></table></section>

    <section class="bloque"><h2>Incidencias</h2><p>Justificaciones, permisos, licencias y observaciones del rango.</p><table><thead><tr><th>Fecha</th><th>Persona</th><th>Tipo</th><th>Motivo</th><th>Estado</th><th>Registrada</th><th>Resuelta</th></tr></thead><tbody><?php foreach ($incidencias as $fila): ?><tr><td><?= htmlspecialchars($fila['fecha']) ?></td><td><?= htmlspecialchars($fila['persona']) ?></td><td><?= htmlspecialchars(str_replace('_',' ',$fila['tipo'])) ?></td><td><?= htmlspecialchars($fila['motivo']) ?></td><td><?= htmlspecialchars($fila['estado']) ?></td><td><?= htmlspecialchars($fila['creado_en']) ?></td><td><?= htmlspecialchars($fila['resuelto_en'] ?: 'Pendiente') ?></td></tr><?php endforeach; ?><?php if(!$incidencias): ?><tr><td colspan="7" class="sin-datos">Sin incidencias</td></tr><?php endif; ?></tbody></table></section>
    <?php endif; ?>
    <footer class="pie"><span>Reporte institucional de uso interno</span><span><?= htmlspecialchars($institucion['nombre'] ?? 'Colegio') ?></span></footer>
</main>
</body>
</html>
